import {evaluate,TurnFence,ApprovalStore} from './policy.mjs';
export class Runtime {
 constructor({model,speech,storage,emit,delay=0}){Object.assign(this,{model,speech,storage,emit,delay});this.fence=new TurnFence();this.approvals=new ApprovalStore();this.history=[];this.lastSpeech=null;this.audit=[];this.busy=false}
 event(type,data={}){const row={type,...data,at:new Date().toISOString()};this.emit(row);if(['policy','tool','cancel','error','approved','heard'].includes(type)){this.audit.push(row);this.storage.audit?.(row)}}
 cancel(){this.fence.cancel();this.approvals.clear();this.busy=false;if(this.lastSpeech){this.history.push({role:'system',content:'The previous spoken response was interrupted and may not have been heard in full. Do not assume it was delivered.'});this.lastSpeech=null}this.event('cancel');}
 async say(text,id){if(!this.fence.active(id))return;this.history.push({role:'assistant',content:text});this.lastSpeech={id,text};this.event('response',{text,turn:id});if(this.speech){try{await this.speech(text,this.fence.controller.signal,chunk=>{if(this.fence.active(id))this.event('audio',{turn:id,chunk})});if(this.fence.active(id))this.event('audio-end',{turn:id})}catch(e){if(this.fence.active(id))this.event('speech-error',{message:e.message,turn:id})}}}
 async run(text){if(typeof text!=='string'||!text.trim()||text.length>4000)throw new Error('Enter a request of 1–4,000 characters.');this.cancel();const {id,signal}=this.fence.next();this.busy=true;this.event('start',{text,turn:id});this.history.push({role:'user',content:text});try{this.event('state',{state:'Thinking',turn:id});const result=await this.model(this.history.slice(-16),signal,token=>{if(this.fence.active(id))this.event('token',{token,turn:id})});if(!this.fence.active(id))return;if(result.action){const action=structuredClone(result.action),verdict=evaluate(action);this.event('policy',{...verdict,action,turn:id});if(verdict.decision==='block'){await this.say(verdict.reason,id)}else if(verdict.decision==='approval'){const approvalId=this.approvals.create(action,id);this.event('approval',{approvalId,action,reason:verdict.reason,turn:id});await this.say('I’m ready to save '+action.args.title+'. Please review the proposed memory and approve it on screen. Nothing has been saved yet.',id)}else await this.execute(action,id,signal)}else {const text=String(result.text||'Please ask a question about your workspace.').slice(0,3000);await this.say(text,id)}}catch(e){if(this.fence.active(id))this.event('error',{message:e.message,turn:id})}finally{if(this.fence.active(id)){this.busy=false;this.event('state',{state:'Ready',turn:id})}}}
 async approve(approvalId,accepted){const id=this.fence.current,action=this.approvals.take(approvalId,id);if(!accepted){this.event('policy',{decision:'block',rule:'USER-DENIED',reason:'You declined this action.',action,turn:id});return}const verdict=evaluate(action);if(verdict.decision!=='approval')throw new Error('Action is no longer eligible for approval.');this.event('approved',{action,turn:id});await this.execute(action,id,this.fence.controller.signal)}
 async execute(action,id,signal){if(!this.fence.active(id))return;this.event('state',{state:'Working',turn:id});if(this.delay)await new Promise((resolve,reject)=>{const t=setTimeout(resolve,this.delay);signal.addEventListener('abort',()=>{clearTimeout(t);reject(new Error('Cancelled'))},{once:true})});if(!this.fence.active(id))return;let result;
 if(action.tool==='search_memory'){const q=action.args.query.toLowerCase();const memory=await this.storage.read();if(!this.fence.active(id))return;result=memory.filter(m=>(m.title+' '+m.content).toLowerCase().includes(q));this.event('tool',{name:action.tool,result,count:result.length,turn:id});const words=result.length?result.slice(0,3).map(m=>m.title+': '+m.content).join(' '):'No matching memories. Try a different phrase.';await this.say(words.slice(0,2200),id)}
 else if(action.tool==='save_memory'){const record={id:crypto.randomUUID(),...action.args,kind:'idea',links:[],source:'User-approved memory',createdAt:new Date().toISOString()};await this.storage.add(record,()=>this.fence.active(id));if(!this.fence.active(id)){this.event('tool',{name:action.tool,turn:id,message:'Write was cancelled or may have completed before interruption; inspect memory.'});return}this.event('tool',{name:action.tool,result:record,turn:id});await this.say('Saved '+record.title+' to your memory.',id)}
 }
 heard(turn){if(this.lastSpeech?.id===turn){this.event('heard',{turn,text:this.lastSpeech.text});this.lastSpeech=null}}
}
